<?php
require 'config.php';if(empty($_SESSION['cart']))go('cart.php');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(!$name||!$phone||!$address){$error='Lengkapi semua data.';}else{try{$pdo->beginTransaction();$ids=array_keys($_SESSION['cart']);$total=0;$lines=[];$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND active=1 FOR UPDATE");foreach($_SESSION['cart'] as $id=>$qty){$s->execute([(int)$id]);$p=$s->fetch();$qty=(int)$qty;if(!$p||$qty<1||$p['stock']<$qty)throw new Exception('Stok produk berubah. Periksa kembali keranjang.');$total+=$p['price']*$qty;$lines[]=[$p,$qty];}
$o=$pdo->prepare("INSERT INTO orders(customer_name,phone,address,total,status) VALUES(?,?,?,?, 'Menunggu')");$o->execute([$name,$phone,$address,$total]);$orderId=(int)$pdo->lastInsertId();$oi=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)");$up=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=?");foreach($lines as [$p,$qty]){$oi->execute([$orderId,$p['id'],$p['name'],$p['price'],$qty]);$up->execute([$qty,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$orderId;go('success.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}
$total=0;foreach($_SESSION['cart'] as $id=>$qty){$s=$pdo->prepare("SELECT price FROM products WHERE id=?");$s->execute([(int)$id]);$r=$s->fetch();if($r)$total+=$r['price']*(int)$qty;}
$page_title='Checkout';require 'header.php';?><h1>Checkout</h1><div class="checkout-layout"><form method="post" class="panel"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php if(!empty($error)):?><p class="alert"><?=e($error)?></p><?php endif;?><label>Nama lengkap<input name="customer_name" required value="<?=e($_POST['customer_name']??'')?>"></label><label>Nomor telepon<input name="phone" required value="<?=e($_POST['phone']??'')?>"></label><label>Alamat pengiriman<textarea name="address" rows="4" required><?=e($_POST['address']??'')?></textarea></label><button class="btn">Buat pesanan</button></form><aside class="panel"><h3>Ringkasan</h3><h2><?=rupiah($total)?></h2><small>Stok akan dikurangi setelah pesanan berhasil dibuat.</small></aside></div><?php require 'footer.php';?>